    raw.clamp(MIN_ITERATIONS, MAX_ITERATIONS)
}

fn run_bench<B: Bench>(bench: &mut B, iterations: u64, inner: u64) -> (Histogram<u64>, f64) {
    // 1 ns to 60 s, 3 sig figs
    let mut hist = Histogram::<u64>::new_with_bounds(1, 60_000_000_000, 3).unwrap();

    let run_start = minstant::Instant::now();
    for _ in 0..iterations {
        let start = minstant::Instant::now();
        for _ in 0..inner {
            black_box(bench.step());
        }
        let elapsed_ns = start.elapsed().as_nanos() as u64;
        hist.record(round_elapsed(elapsed_ns, inner)).unwrap();
    }
    let duration_s = run_start.elapsed().as_nanos() as f64 / 1e9;

    (hist, duration_s)
}

fn round_elapsed(elapsed_ns: u64, inner: u64) -> u64 {
    (elapsed_ns + inner / 2) / inner
}

pub fn fmt_commas(n: u64) -> String {
    let s = n.to_string();
    let mut result = String::new();
    for (i, c) in s.chars().rev().enumerate() {
        if i > 0 && i % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    result.chars().rev().collect()
}

pub fn fmt_commas_f64(n: f64, decimals: usize) -> String {
    let s = format!("{n:.decimals$}");
    let (sign, body) = match s.strip_prefix('-') {
        Some(rest) => ("-", rest),
        None => ("", s.as_str()),
    };
    let (int_part, frac_part) = match body.find('.') {
        Some(i) => (&body[..i], &body[i..]),
        None => (body, ""),
    };
    let int_num: u64 = int_part.parse().unwrap_or(0);
    format!("{sign}{}{frac_part}", fmt_commas(int_num))
}

pub fn print_histogram(
    name: &str,
    iterations: u64,
    inner: u64,
    hist: &Histogram<u64>,
    overhead: &Overhead,
) {
    let adj = overhead.per_call_ns(inner);
    let total = iterations * inner;
    println!(
        "{name} ({} iters × {} inner = {} calls; subtract {} ns/call)",
        fmt_commas(iterations),
        inner,
        fmt_commas(total),
        fmt_commas_f64(adj, 2),
    );
    println!("                      raw      adjusted");
    print_row("min", hist.min(), adj);
    print_row("p1", hist.value_at_quantile(0.01), adj);
    print_row("p10", hist.value_at_quantile(0.10), adj);
    print_row("p50", hist.value_at_quantile(0.50), adj);
    print_row("p90", hist.value_at_quantile(0.90), adj);
    print_row("p99", hist.value_at_quantile(0.99), adj);
    print_row("p99.9", hist.value_at_quantile(0.999), adj);
    print_row("p99.99", hist.value_at_quantile(0.9999), adj);
    print_row("max", hist.max(), adj);
    let mean = hist.mean();
    let adj_mean = (mean - adj).max(0.0);
    println!(
        "  mean       {:>10} ns    {:>10} ns",
        fmt_commas_f64(mean, 1),
        fmt_commas_f64(adj_mean, 1)
    );
    println!("  stdev      {:>10} ns", fmt_commas_f64(hist.stdev(), 1));
    println!();
}

fn print_row(label: &str, raw: u64, overhead: f64) {
    let adj = (raw as f64 - overhead).max(0.0);
    println!(
        "  {label:<8} {:>10} ns    {:>10} ns",
        fmt_commas(raw),
        fmt_commas_f64(adj, 1)
    );
}

use std::hint::black_box;
use std::sync::mpsc;
use std::thread;

use crate::harness::{self, Bench, RunCfg};

pub const NAME: &str = "mpsc-2t";

pub struct StdMpsc2Thread {
    req_tx: mpsc::Sender<u64>,
    resp_rx: mpsc::Receiver<u64>,
    worker: Option<thread::JoinHandle<()>>,
    counter: u64,
}

impl StdMpsc2Thread {
    pub fn new() -> Self {
        let (req_tx, req_rx) = mpsc::channel::<u64>();
        let (resp_tx, resp_rx) = mpsc::channel::<u64>();
        let worker = thread::spawn(move || {
            while let Ok(v) = req_rx.recv() {
                if resp_tx.send(v).is_err() {
                    break;
                }
            }
        });
        Self {
            req_tx,
            resp_rx,
            worker: Some(worker),
            counter: 0,
        }
    }
}

impl Bench for StdMpsc2Thread {
    fn name(&self) -> &str {
        "std::sync::mpsc round-trip (2 threads)"
    }

    fn step(&mut self) -> u64 {
        self.counter = self.counter.wrapping_add(1);
        self.req_tx.send(self.counter).unwrap();
        let v = self.resp_rx.recv().unwrap();
        black_box(v)
    }
}

impl Drop for StdMpsc2Thread {
    fn drop(&mut self) {
        // Replace req_tx with a dummy so we can drop the real one;
        // worker's recv() then returns Err and the worker exits.
        // Done this way (instead of Option<Sender>) to keep step() branch-free.
        let (dummy_tx, _) = mpsc::channel();
        drop(std::mem::replace(&mut self.req_tx, dummy_tx));
        if let Some(worker) = self.worker.take() {
            let _ = worker.join();
        }
    }
}

pub fn run(cfg: &RunCfg) {
    let mut bench = StdMpsc2Thread::new();
    let (hist, iterations, inner) = harness::run_adaptive(&mut bench, cfg);
    harness::print_histogram(bench.name(), iterations, inner, &hist, cfg.overhead);
}

