    // each column so commas/decimals never overflow the field.
    let raw_w = rows.iter().map(|(_, r, _)| r.len()).max().unwrap_or(0);
    let adj_w = rows
        .iter()
        .filter_map(|(_, _, a)| a.as_ref().map(String::len))
        .max()
