pub fn print_histogram(
    name: &str,
    iterations: u64,
    inner: u64,
    duration_s: f64,
    hist: &Histogram<u64>,
    overhead: &Overhead,
) {
    // Header line: bench name + logfmt-style metadata. `adj` is the
    // apparatus overhead subtracted from each sample downstream.
    let adj = overhead.per_call_ns(inner);
    let total = iterations * inner;
    println!(
        "{name} [duration={:.1}s outer={} inner={} calls={} adj/call={}ns]:",
        duration_s,
        fmt_commas(iterations),
        inner,
        fmt_commas(total),
        fmt_commas_f64(adj, 2),
    );

    // Each row is (label, raw, adj?). stdev has no adjusted column since
    // subtracting overhead from a spread measure is meaningless, hence
    // the Option. Values are formatted up front so column widths below
    // can be derived from the actual rendered strings.
    let rows: Vec<Row> = vec![
        row_u64("min", hist.min(), adj),
        row_u64("p1", hist.value_at_quantile(0.01), adj),
        row_u64("p10", hist.value_at_quantile(0.10), adj),
        row_u64("p50", hist.value_at_quantile(0.50), adj),
        row_u64("p90", hist.value_at_quantile(0.90), adj),
        row_u64("p99", hist.value_at_quantile(0.99), adj),
        row_u64("p99.9", hist.value_at_quantile(0.999), adj),
        row_u64("p99.99", hist.value_at_quantile(0.9999), adj),
        row_u64("max", hist.max(), adj),
        row_f64("mean", hist.mean(), adj),
        row_raw_only("stdev", hist.stdev()),
    ];

    // Column widths are data-driven: take the widest rendered string in
    // each column so commas/decimals never overflow the field.
    let raw_w = rows.iter().map(|(_, r, _)| r.len()).max().unwrap_or(0);
    let adj_w = rows
        .iter()
        .filter_map(|(_, _, a)| a.as_ref().map(String::len))
        .max()
        .unwrap_or(0);

    // Fixed layout pieces: 2-space indent, 8-wide label, 4-space gap
    // between the raw and adjusted columns.
    const INDENT: &str = "  ";
    const LABEL_W: usize = 8;
    const GAP: &str = "    ";

    // "raw"/"adjusted" header sits over the numeric columns. We right-
    // align each label to the right-edge of its column (just before the
    // " ns" suffix), computed from indent + label + width + " ns" + gap.
    let raw_col_end = INDENT.len() + LABEL_W + 1 + raw_w;
    let adj_col_end = " ns".len() + GAP.len() + adj_w;
    println!(
        "{:>raw_col_end$}{:>adj_col_end$}",
        "raw",
        "adjusted",
    );

    // Data rows: label left-aligned, numbers right-aligned in their
    // data-driven widths. Rows with no adjusted value skip that column.
    for (label, raw_s, adj_s) in &rows {
        match adj_s {
            Some(a) => println!("{INDENT}{label:<LABEL_W$} {raw_s:>raw_w$} ns{GAP}{a:>adj_w$} ns"),
            None => println!("{INDENT}{label:<LABEL_W$} {raw_s:>raw_w$} ns"),
        }
    }
    println!();
}

type Row = (&'static str, String, Option<String>);

fn row_u64(label: &'static str, raw: u64, adj: f64) -> Row {
    (
        label,
        fmt_commas(raw),
        Some(fmt_commas_f64((raw as f64 - adj).max(0.0), 1)),
    )
}

fn row_f64(label: &'static str, raw: f64, adj: f64) -> Row {
    (
        label,
        fmt_commas_f64(raw, 1),
        Some(fmt_commas_f64((raw - adj).max(0.0), 1)),
    )
}

fn row_raw_only(label: &'static str, raw: f64) -> Row {
    (label, fmt_commas_f64(raw, 1), None)
}

