    let int_num: u64 = int_part.parse().unwrap_or(0);
    format!("{sign}{}{frac_part}", fmt_commas(int_num))
}

pub fn print_histogram(
    name: &str,
    iterations: u64,
    inner: u64,
    duration_s: f64,
    hist: &Histogram<u64>,
    overhead: &Overhead,
) {
    // Header line: bench name + logfmt-style metadata. `adj` is the
    // apparatus overhead subtracted from each sample downstream.
    let adj = overhead.per_call_ns(inner);
    let total = iterations * inner;
    println!(
        "{name} [duration={:.1}s outer={} inner={} calls={} adj/call={}ns]:",
        duration_s,
        fmt_commas(iterations),
        inner,
        fmt_commas(total),
        fmt_commas_f64(adj, 2),
    );

    // Each Row carries the numeric values plus a `decimals` hint matching
    // the stat's actual precision: 0 for percentile/min/max (integer-ns
    // histogram samples; sub-ns in adj would be overhead-subtraction
    // arithmetic, not measurement precision), 1 for mean/stdev (averaging
    // over N samples recovers genuine sub-ns structure). stdev has no
    // adjusted column since subtracting overhead from a spread is
    // meaningless.
    let rows: Vec<Row> = vec![
        Row::integer("min", hist.min(), adj),
        Row::integer("p1", hist.value_at_quantile(0.01), adj),
        Row::integer("p10", hist.value_at_quantile(0.10), adj),
        Row::integer("p50", hist.value_at_quantile(0.50), adj),
        Row::integer("p90", hist.value_at_quantile(0.90), adj),
        Row::integer("p99", hist.value_at_quantile(0.99), adj),
        Row::integer("p99.9", hist.value_at_quantile(0.999), adj),
        Row::integer("p99.99", hist.value_at_quantile(0.9999), adj),
        Row::integer("max", hist.max(), adj),
        Row::float("mean", hist.mean(), adj),
        Row::raw_only("stdev", hist.stdev()),
    ];

    // Render each row to its final strings so we can size columns from
    // the actual widths. Each row's raw and adj use the same decimals.
    let rendered: Vec<(&str, String, Option<String>)> = rows
        .iter()
        .map(|r| {
            (
                r.label,
                fmt_commas_f64(r.raw, r.decimals),
                r.adj.map(|a| fmt_commas_f64(a, r.decimals)),
            )
        })
        .collect();

    // Column widths: widest rendered string in each column.
    let raw_w = rendered.iter().map(|(_, r, _)| r.len()).max().unwrap_or(0);
    let adj_w = rendered
        .iter()
        .filter_map(|(_, _, a)| a.as_ref().map(String::len))
        .max()
        .unwrap_or(0);

    // Fixed layout pieces: 2-space indent, 8-wide label, 4-space gap
    // between the raw and adjusted columns.
    const INDENT: &str = "  ";
    const LABEL_W: usize = 8;
    const GAP: &str = "    ";

    // "raw"/"adjusted" header sits over the numeric columns. We right-
    // align each label to the right-edge of its column (just before the
    // " ns" suffix).
    let raw_col_end = INDENT.len() + LABEL_W + 1 + raw_w;
    let adj_col_end = " ns".len() + GAP.len() + adj_w;
    println!("{:>raw_col_end$}{:>adj_col_end$}", "raw", "adjusted",);

    // Data rows: label left-aligned, numbers right-aligned in their
    // data-driven widths. Rows with no adjusted value skip that column.
    for (label, raw_s, adj_s) in &rows {
        match adj_s {
            Some(a) => println!("{INDENT}{label:<LABEL_W$} {raw_s:>raw_w$} ns{GAP}{a:>adj_w$} ns"),
            None => println!("{INDENT}{label:<LABEL_W$} {raw_s:>raw_w$} ns"),
        }
    }
    println!();
}

type Row = (&'static str, String, Option<String>);

fn row_u64(label: &'static str, raw: u64, adj: f64) -> Row {
    (
        label,
        fmt_commas(raw),
        Some(fmt_commas_f64((raw as f64 - adj).max(0.0), 1)),
    )
}

fn row_f64(label: &'static str, raw: f64, adj: f64) -> Row {
    (
        label,
        fmt_commas_f64(raw, 1),
        Some(fmt_commas_f64((raw - adj).max(0.0), 1)),
    )
}

fn row_raw_only(label: &'static str, raw: f64) -> Row {
    (label, fmt_commas_f64(raw, 1), None)
}

content.text:
Agreed — 100ps precision is a false promise. With ~1ns timer res and ~25% run-to-run duration variance, the `.1` is numerical seasoning.

Also lets me simplify the struct further (no `decimals` field needed) and drop one constructor:

```rust
struct Row {
    label: &'static str,
    raw: f64,
    adj: Option<f64>,
}

impl Row {
    fn with_adj(label: &'static str, raw: f64, overhead: f64) -> Self {
        Self { label, raw, adj: Some((raw - overhead).max(0.0)) }
    }
    fn raw_only(label: &'static str, raw: f64) -> Self {
        Self { label, raw, adj: None }
    }
}
```

Call sites all pass f64 (histogram u64 methods get a single `as f64` cast):
```rust
Row::with_adj("min",    hist.min() as f64,                    adj),
Row::with_adj("p1",     hist.value_at_quantile(0.01) as f64,  adj),
...
Row::with_adj("mean",   hist.mean(),                          adj),
Row::raw_only("stdev",  hist.stdev()),
```

Implementing now. The duration miss (60→46.8 / 35.7 = 22%–40% undershoot) is a separate adaptive-sizing issue worth a follow-up — estimator runs on cold samples and the picked iteration count underestimates when the real loop is faster than the startup probe. I'll flag as a followup once this lands.

